package com.robotkinematicslab.mobile.ui.help

data class ResearchGlossaryEntry(
    val term: String,
    val plainMeaning: String,
    val whyItMatters: String
)

/** Scientific terminology used by inline help and the searchable glossary. */
object ResearchGlossaryCatalog {
    val entries: List<ResearchGlossaryEntry> =
        com.robotkinematicslab.mobile.ui.workspace.WorkspaceQualityPreset.entries.map { preset ->
            ResearchGlossaryEntry("${preset.label} workspace preset", preset.explanation, "${preset.exactSummary}. Seed and device policy are unchanged.")
        } + listOf(
            ResearchGlossaryEntry("DH parameters", "Four values that describe how one robot frame is positioned relative to the previous frame.", "A wrong convention or offset changes every downstream pose."),
            ResearchGlossaryEntry("Forward kinematics (FK)", "Calculates the end-effector pose from known joint values.", "It is the deterministic reference used to create reachable targets and check results."),
            ResearchGlossaryEntry("Inverse kinematics (IK)", "Searches for joint values that place the end effector at a requested target.", "IK can have several solutions, no solution, or stop near the target without meeting tolerance."),
            ResearchGlossaryEntry("Tolerance", "The maximum final position error accepted as success.", "Changing tolerance changes labels and makes two experiments incomparable unless reported."),
            ResearchGlossaryEntry("Residual / final error", "The distance still remaining between requested and achieved target after solving.", "Lower is better only when units and tolerance are identical."),
            ResearchGlossaryEntry("Seed", "A number that reproduces the same pseudo-random choices.", "It supports repeatability; several seeds reveal whether a result depends on luck."),
            ResearchGlossaryEntry("Topology", "The structural family of a robot, such as link count and joint-type sequence.", "Aggregate results can hide failures concentrated in one topology."),
            ResearchGlossaryEntry("Reachable target", "A target produced or verified inside the robot's valid joint-limited workspace.", "Reachability depends on the complete mechanism and limits, not distance alone."),
            ResearchGlossaryEntry("Point cloud", "The individual sampled 3D positions reached by valid robot configurations.", "It shows the underlying observations rather than an interpolated boundary."),
            ResearchGlossaryEntry("Surface shell", "A transparent boundary reconstructed from occupied workspace cells.", "It makes the outer envelope easier to see, but remains an empirical approximation."),
            ResearchGlossaryEntry("Dead space", "A region inside or near the overall envelope that valid configurations cannot reach.", "Joint restrictions and mechanism geometry can create internal cavities."),
            ResearchGlossaryEntry("Workspace convergence", "The change in estimated occupied volume as more joint states are sampled.", "A flattening curve increases confidence that more samples will not radically change the observed envelope."),
            ResearchGlossaryEntry("Dataset manifest", "The stored contract describing how a dataset was generated.", "It binds rows to robots, seeds, solver settings, filters and provenance."),
            ResearchGlossaryEntry("Continuous dataset growth", "Repeated generation of small batches while the app process remains active.", "It can grow evidence without blocking navigation, while keeping cancellation and recovery bounded."),
            ResearchGlossaryEntry("Atomic batch", "A group of rows committed completely or not accepted at all.", "It prevents interruption from leaving a half-written batch presented as valid evidence."),
            ResearchGlossaryEntry("Class support", "The number of true test examples belonging to each outcome class.", "A score for a missing class is not measured and a complete macro comparison is invalid."),
            ResearchGlossaryEntry("Macro-F1", "The unweighted mean of the F1 score calculated for each represented class.", "It balances classification precision and recall, but must be read with class support."),
            ResearchGlossaryEntry("Held-out test set", "Samples kept untouched until final evaluation.", "It estimates generalisation only when training and model selection never used those samples."),
            ResearchGlossaryEntry("Data leakage", "Information from the test group accidentally influences training.", "Leakage makes a model look better than it will be on genuinely unseen robots or samples."),
            ResearchGlossaryEntry("Feature profile", "A named and versioned selection of model input variables.", "It makes comparisons between ordinary kinematics and added context explicit and repeatable."),
            ResearchGlossaryEntry("Feature count", "The number of input variables supplied to a model.", "It measures input width, but does not identify which variables are present or whether they are useful."),
            ResearchGlossaryEntry("Deterministic recovery", "A conventional solver attempt used after an AI proposal fails verification.", "It improves pipeline reliability but must not be reported as pure AI success."),
            ResearchGlossaryEntry("Numerical drift", "Small floating-point deviations that accumulate across calculations.", "Safety checks prevent non-finite or invalid transforms from silently contaminating evidence."),
            ResearchGlossaryEntry("Protected / unguarded branch", "Two calculations using the same base inputs, with the numerical safety stack enabled or deliberately bypassed.", "The pairing isolates the measured effect of the safeguards."),
            ResearchGlossaryEntry("Fault injection", "A deliberately corrupted input used to test defensive containment.", "It proves how the system reacts to a fault, not how often that fault occurs naturally."),
            ResearchGlossaryEntry("Telemetry", "Time-ordered measurements of progress, rate, memory, runtime, scheduling and thermal conditions.", "It helps diagnose performance and execution conditions without changing the scientific output."),
            ResearchGlossaryEntry("Research activity centre", "The in-app list of active and recently completed long calculations.", "It remains the authoritative place to inspect progress and full errors even when Android notifications are blocked."),
            ResearchGlossaryEntry("Foreground notification", "Android's visible status for a long user-started calculation while the app process is active.", "It improves visibility but cannot override force-stop, reboot or an operating-system process kill."),
            ResearchGlossaryEntry("Committed checkpoint", "A durable boundary written and verified before a long process advances.", "After interruption, only committed work may be reported or resumed; a partial batch must not masquerade as complete."),
            ResearchGlossaryEntry("Force-stop", "An Android action that terminates the app process and prevents background work from continuing.", "No in-app setting can bypass it; reopen the app and inspect the last committed evidence."),
            ResearchGlossaryEntry("Provenance", "The stored record of where data came from and which settings created it.", "It is what makes an experiment auditable and reproducible."),
            ResearchGlossaryEntry("Worker", "One parallel computation lane used by generation or training.", "More workers can improve throughput but also increase memory use and thermal pressure."),
            ResearchGlossaryEntry("App heap", "The memory allowance Android exposes to this application process.", "It can be much smaller than physical RAM and remains the real ceiling for ordinary managed allocations."),
            ResearchGlossaryEntry("Calibration", "How closely prediction confidence matches observed correctness.", "A model saying 90% should be correct about 90% of the time in comparable data."),
            ResearchGlossaryEntry("Integrated Gradients", "An attribution method that accumulates how inputs change a model's output from a reference to one example.", "It provides signed local contributions whose completeness should be checked."),
            ResearchGlossaryEntry("Feature ablation", "Retraining after removing one feature or feature family while holding the experiment contract fixed.", "It tests whether that information earns its accuracy and compute cost."),
            ResearchGlossaryEntry("Research pack", "Versioned datasets and trained models generated on the computer and compressed inside the APK.", "It makes heavy evidence available on a phone without repeating the full computation."),
            ResearchGlossaryEntry("One-micron verification", "A contract requiring the final position error to be no more than 0.001 mm.", "It is much stricter than ordinary visual accuracy and often needs deterministic verification."),
            ResearchGlossaryEntry("Jacobian", "A matrix that relates small joint movements to motion of the robot tool.", "Its rank and conditioning reveal directions that are difficult or impossible for the mechanism to produce."),
            ResearchGlossaryEntry("Singularity", "A robot configuration where motion or force is lost in at least one Cartesian direction.", "Near a singularity, tiny target changes can require very large joint changes and make inverse kinematics unstable."),
            ResearchGlossaryEntry("Condition number", "A scale-free measure of how strongly numerical error can be amplified by a matrix operation.", "A large value warns that an apparently small input or rounding error may produce an unreliable motion estimate."),
            ResearchGlossaryEntry("Non-finite value", "A numeric result such as NaN or positive/negative infinity that is not an ordinary finite number.", "Allowing one non-finite value into a transform or dataset can contaminate every downstream calculation."),
            ResearchGlossaryEntry("End effector", "The tool or final frame at the end of the robot chain.", "Targets and residuals refer to this frame, so its offset and convention must be explicit."),
            ResearchGlossaryEntry("Revolute joint", "A joint whose controlled displacement is an angle.", "Its angular limits and axis determine the curved part of the robot workspace."),
            ResearchGlossaryEntry("Prismatic joint", "A joint whose controlled displacement is a linear translation.", "Its travel limits determine straight sections of the robot workspace and must use consistent distance units."),
            ResearchGlossaryEntry("Classification precision", "Among predictions assigned to a class, the fraction that are actually correct.", "High classification precision means few false positives, but it says nothing by itself about missed cases."),
            ResearchGlossaryEntry("Recall", "Among true members of a class, the fraction that the model finds.", "High recall means few false negatives, but it must be read together with classification precision and class support."),
            ResearchGlossaryEntry("Sensitivity analysis", "A controlled check of how much an output changes when a seed, parameter or input is varied.", "It reveals fragile results and parameter dependence; it is different from classification recall, which is sometimes also called sensitivity."),
            ResearchGlossaryEntry("Numerical precision", "The fineness and repeatability of a numeric result, such as the final IK position error.", "It must be interpreted with units, tolerance and floating-point limits; it is not the classification metric also called precision."),
            ResearchGlossaryEntry("Confusion matrix", "A table crossing true classes with predicted classes.", "It shows which outcomes the model confuses instead of hiding them inside one aggregate score."),
            ResearchGlossaryEntry("Confidence interval", "A range produced by a stated statistical method to express uncertainty around an estimate.", "The method, confidence level and independent sampling unit must be reported before the range is interpretable."),
            ResearchGlossaryEntry("Standard deviation", "A measure of how dispersed observations are around their arithmetic mean.", "It exposes instability that an average alone can hide, but is sensitive to outliers and distribution shape."),
            ResearchGlossaryEntry("Percentile", "A threshold below which a stated percentage of observations falls.", "Tail percentiles such as P95 reveal difficult cases that the mean can conceal."),
            ResearchGlossaryEntry("Outlier", "An observation unusually distant from most of its comparison group.", "It may represent a real failure mode, data error or rare topology and should be investigated rather than deleted automatically."),
            ResearchGlossaryEntry("Latency", "Elapsed time between starting an operation and obtaining its result.", "Lower latency improves responsiveness, but it must not be achieved by reducing validation or result quality."),
            ResearchGlossaryEntry("Throughput", "The number of completed calculations or samples per unit of time.", "It measures processing capacity and must be interpreted with the same workload, device state and quality checks."),
            ResearchGlossaryEntry("Epoch", "One complete pass through the training examples available to the model.", "Too few epochs can underfit; too many can overfit, so validation behaviour matters more than the count alone."),
            ResearchGlossaryEntry("Overfitting", "When a model learns the training examples too specifically and performs worse on unseen data.", "A growing gap between training and held-out performance warns that apparent progress may not generalise."),
            ResearchGlossaryEntry("Mean squared error (MSE)", "The average squared difference between predicted and reference numeric values.", "Lower is normally better, but squaring makes large errors dominate and the value depends on the measurement scale."),
            ResearchGlossaryEntry("Area under the curve (AUC)", "A single summary of a performance curve over a stated range of thresholds or coverage.", "It is only comparable when the curve definition, axes, range and population are the same."),
            ResearchGlossaryEntry("False positive", "A case predicted as accepted or positive when the reference says it is not.", "In this project it can present an unsafe or unreachable proposal as usable, so its cost may be greater than an ordinary classification error."),
            ResearchGlossaryEntry("False negative", "A valid case predicted as rejected or negative.", "It reduces useful coverage and can make a model appear safer by refusing cases it could have solved."),
            ResearchGlossaryEntry("Damped least squares (DLS)", "An inverse-kinematics update that adds damping before solving the Jacobian system.", "Damping improves stability near singularities, but too much damping can slow convergence or leave a larger residual."),
            ResearchGlossaryEntry("Singular value decomposition (SVD)", "A matrix factorisation that separates directions and their numerical strengths.", "It provides a stable way to inspect rank, singular directions and conditioning in robot Jacobians."),
            ResearchGlossaryEntry("Manipulability", "A local measure of how freely the robot can move its tool in different Cartesian directions.", "Low manipulability warns that the current configuration is close to losing a useful motion direction."),
            ResearchGlossaryEntry("Out-of-distribution (OOD)", "An input that differs materially from the data used to fit and validate the model.", "Model scores on familiar data do not guarantee reliable behaviour on unseen robot families or operating regions."),
            ResearchGlossaryEntry("Root mean square (RMS)", "The square root of the average squared values.", "It preserves the original unit while weighting large deviations more strongly than an ordinary mean absolute value."),
            ResearchGlossaryEntry("Logarithmic scale", "An axis where equal spacing represents multiplication rather than equal addition.", "It makes orders of magnitude visible, but distances cannot be interpreted as ordinary linear differences."),
            ResearchGlossaryEntry("Tail risk", "A summary of unusually difficult observations near the worst end of a distribution, such as P95, P99 or CVaR.", "It reveals rare but important failures that average performance can hide."),
            ResearchGlossaryEntry("Expected calibration error (ECE)", "A binned estimate of the gap between stated confidence and observed accuracy.", "Lower is normally better, but the result depends on the binning rule and sample support."),
            ResearchGlossaryEntry("Brier score", "The mean squared difference between predicted probabilities and one-hot outcomes.", "It measures probability quality rather than just the final class; lower is better on the same task and class encoding."),
            ResearchGlossaryEntry("Risk-coverage curve", "A curve showing prediction error as the model is allowed to abstain from more uncertain cases.", "It exposes the trade-off between serving more cases and keeping the accepted subset reliable."),
            ResearchGlossaryEntry("Conformal prediction", "A method that returns a prediction set using a held-out calibration procedure and a declared error level.", "Its coverage guarantee depends on exchangeability and a calibration set that was not reused for training."),
            ResearchGlossaryEntry("Multilayer perceptron (MLP)", "A feed-forward neural network made from successive learned linear layers and nonlinear activations.", "Its capacity, regularisation and feature scaling affect both fit quality and generalisation."),
            ResearchGlossaryEntry("ONNX model", "A portable graph format used to move a trained model between compatible runtimes.", "Export parity must be checked because preprocessing or unsupported operations can make phone inference differ from computer evaluation."),
            ResearchGlossaryEntry("Logit", "A model's raw score before it is converted into a probability.", "Logits are useful for loss calculations and explanation, but they are not calibrated probabilities by themselves."),
            ResearchGlossaryEntry("Garbage collection (GC)", "Automatic recovery of managed memory that is no longer referenced.", "Frequent or blocking collections can interrupt throughput and reveal excessive allocation during long runs."),
            ResearchGlossaryEntry("System on chip (SoC)", "The integrated chip containing the phone's CPU and other processing components.", "Its temperature and scheduling limits affect sustainable performance even when the app requests more workers."),
            ResearchGlossaryEntry("SHA-256", "A cryptographic digest used here as a compact fingerprint of stored bytes.", "A matching digest helps prove a file is unchanged; it does not by itself prove that the scientific contents are correct."),
            ResearchGlossaryEntry("Joint-space samples", "Joint configurations evaluated with FK, including deterministic limit probes.", "The sample count is a total budget shared across replications, not a count per joint or per replication."),
            ResearchGlossaryEntry("Voxel resolution", "The number of Cartesian cells along each x, y and z axis of the cube around the radial bound.", "20³ means 20 × 20 × 20 cells before envelope filtering. This discretizes end-effector position, not joint angles."),
            ResearchGlossaryEntry("Replications", "Independently shifted Halton sequences that share the total joint-state budget.", "Comparing their voxel estimates measures variation; more replications leave fewer states per sequence."),
            ResearchGlossaryEntry("Scientific seed", "A signed integer that determines the repeatable shifts and corner probes.", "Keep robot geometry, joint order and limits, numeric configuration and sampling protocol fixed to replay the study."),
            ResearchGlossaryEntry("Voxel", "One cell in a three-dimensional grid used to count or classify sampled workspace volume.", "Voxel size trades spatial detail against memory and sample requirements, and the shell remains resolution dependent."),
            ResearchGlossaryEntry("Area under the risk-coverage curve (AURC)", "A single summary of selective prediction risk across retained coverage levels.", "Lower AURC favours models that remove errors early when uncertain cases are rejected, but comparisons require the same population and coverage range."),
            ResearchGlossaryEntry("Wilson interval", "A confidence interval for a binomial proportion that remains useful near zero or one and with limited sample counts.", "It avoids some overconfidence of the simple normal approximation, but its confidence level and effective independent sample unit must still be reported."),
            ResearchGlossaryEntry("Marginal coverage", "The overall fraction of evaluated cases for which a prediction set contains the reference outcome.", "A correct overall rate can still hide weak coverage in a robot family or operating region, so subgroup evidence remains necessary."),
            ResearchGlossaryEntry("Backtracking", "A solver step that shortens or reverses a proposed update when the full move does not improve the objective safely.", "It can rescue unstable inverse-kinematics steps, but repeated backtracking also signals difficult geometry or an unsuitable step size."),
            ResearchGlossaryEntry("Iteration saturation", "A run that reaches its iteration budget without satisfying the declared success tolerance.", "It separates a budget-limited stop from convergence and prevents an unfinished solve from being reported as success."),
            ResearchGlossaryEntry("Native heap", "Memory allocated outside Android's managed object heap, commonly by native code, graphics or low-level buffers.", "It contributes to real process pressure even when the managed app heap looks safe and therefore must be inspected separately."),
            ResearchGlossaryEntry("Thermal headroom", "An estimate of how much sustainable thermal capacity remains before stronger throttling is expected.", "Low headroom means current throughput may soon fall, so short performance bursts should not be presented as sustained device capability."),
            ResearchGlossaryEntry("Joint limit", "The smallest and largest movement allowed for one robot joint.", "Limits decide which poses are physically permitted and create unreachable or dead-space regions."),
            ResearchGlossaryEntry("Robot pose", "The tool's position and orientation together.", "Two results at the same position can still be different if the tool points in a different direction."),
            ResearchGlossaryEntry("Dataset", "A stored collection of examples used to train, validate or test a model.", "Its robots, labels, generation rules and split determine what a model can legitimately learn and how it may be evaluated."),
            ResearchGlossaryEntry("CSV file", "A plain-text table where each line is one record and commas separate its columns.", "It exposes the evidence for independent inspection, but column names and units are needed to interpret it correctly."),
            ResearchGlossaryEntry("Accepted / rejected case", "An accepted case met the declared checks; a rejected case did not.", "Rejected does not automatically mean physically unreachable: the solver may simply have missed the required tolerance or produced an invalid result."),
            ResearchGlossaryEntry("Solver iteration", "One repeated attempt to move the current robot solution closer to the target.", "More iterations give the solver more opportunities, but also take longer and do not guarantee convergence."),
            ResearchGlossaryEntry("Maximum step", "The largest joint update the solver may apply in one iteration.", "A large step can be fast but unstable; a small step is cautious but may need more iterations."),
            ResearchGlossaryEntry("Normalisation", "Rescaling variables to comparable numeric ranges before model training.", "Without consistent scaling, large-number columns can dominate learning for no scientific reason."),
            ResearchGlossaryEntry("Scientific data split", "The rule that separates examples used for learning, tuning and final testing.", "The split must keep genuinely independent examples out of training or the reported result will be over-optimistic."),
            ResearchGlossaryEntry("Comparison arm", "One complete model-and-feature configuration included in the same controlled comparison.", "Arms are meaningful only when they use the same data split, seeds and evaluation rules."),
            ResearchGlossaryEntry("Model candidate", "One algorithm and hyperparameter configuration tried during model selection.", "Trying more candidates may find a better model, but selection must use validation data rather than the final test set."),
            ResearchGlossaryEntry("Mini-batch", "A small group of training examples processed together before updating the model.", "Batch size changes memory use, update noise and training speed."),
            ResearchGlossaryEntry("Learning rate", "The size of each adjustment made to the model while it learns.", "Too high can make training unstable; too low can make it unnecessarily slow or leave it under-trained."),
            ResearchGlossaryEntry("L2 regularisation", "A penalty that discourages excessively large model weights.", "It can reduce overfitting, but too much can prevent the model from learning useful structure."),
            ResearchGlossaryEntry("Hidden unit", "One learned internal value inside a neural-network layer.", "More units increase capacity and compute cost; they do not guarantee better generalisation."),
            ResearchGlossaryEntry("Early stopping", "Stopping training when validation performance no longer improves.", "It avoids wasting epochs and can reduce overfitting without using the final test set."),
            ResearchGlossaryEntry("Balanced accuracy", "The average recall across classes, giving each class equal weight.", "It is more informative than ordinary accuracy when accepted and rejected examples are imbalanced."),
            ResearchGlossaryEntry("Cross-entropy / log loss", "A score that penalises incorrect predicted probabilities, especially confident wrong answers.", "Lower is better on the same task; unlike accuracy, it checks probability quality as well as the winning class."),
            ResearchGlossaryEntry("Inference", "Using a trained model to make a prediction for a new input.", "Inference speed, memory and export parity determine whether the model is practical on the phone."),
            ResearchGlossaryEntry("Attribution", "An estimate of how much each input variable pushed one model prediction up or down.", "It explains model behaviour, but it is not proof that a variable physically caused the outcome."),
            ResearchGlossaryEntry("SHAP value", "A game-theory-based attribution that compares a feature's contribution across combinations of available features.", "Its meaning depends on the chosen background data and on how dependent features are handled."),
            ResearchGlossaryEntry("Completeness error", "The gap between the change in model output and the sum of the reported attributions.", "A small gap checks numerical consistency; it does not prove that the explanation is scientifically causal."),
            ResearchGlossaryEntry("Decision margin", "The difference between the winning model score and the nearest competing score.", "A small margin means the predicted class could change after a small disturbance even if it is currently correct."),
            ResearchGlossaryEntry("Deterministic reference solver", "The conventional mathematical result used as the comparison reference for an AI prediction.", "It provides a reproducible check, but must itself satisfy the declared numerical and physical validity rules."),
            ResearchGlossaryEntry("Perturbation", "A controlled small change applied to an input during a robustness test.", "It reveals sensitivity only when the change size, unit and affected variables are stated."),
            ResearchGlossaryEntry("Selective risk", "The error rate among predictions the model chooses to keep rather than reject as uncertain.", "It shows the cost of serving more cases: retaining more coverage can leave more errors in the accepted set."),
            ResearchGlossaryEntry("Retained coverage", "The fraction of evaluated cases kept after uncertain predictions are rejected.", "Higher coverage serves more cases, but should be read together with the remaining selective risk."),
            ResearchGlossaryEntry("Evidence artifact", "A saved file such as a dataset, manifest, model, report or figure produced by an experiment.", "Keeping related artifacts together makes a result auditable and reproducible."),
            ResearchGlossaryEntry("Quarantine", "Preserving a suspicious file while excluding it from trusted experiments.", "It avoids data loss while preventing an incomplete or inconsistent artifact from being used silently."),
            ResearchGlossaryEntry("Logical CPU core", "One processing lane reported by Android; several may share the same physical hardware resources.", "Using every logical core can increase short bursts of work but may also trigger heat and throttling."),
            ResearchGlossaryEntry("Working-memory budget", "The maximum temporary memory this app is allowed to plan for during a calculation.", "It stays below the phone's total RAM so Android and essential work retain safe headroom."),
            ResearchGlossaryEntry("Thermal throttling", "Automatic slowing of the processor when the device becomes too hot.", "A fast initial rate may fall during a long experiment, so sustained performance and temperature must be reported together."),
            ResearchGlossaryEntry("Processing thread", "One operating-system execution stream assigned work by the application.", "Thread count can change scheduling, memory pressure and throughput; it does not change the scientific contract by itself."),
            ResearchGlossaryEntry("Sample", "One observation or generated case with its inputs, reference outcome and recorded metadata.", "Rows are only interchangeable samples when they follow the same schema, units and generation contract."),
            ResearchGlossaryEntry("Append operation", "Adding a committed batch to an existing dataset instead of replacing its prior rows.", "Append is safe only when the saved and requested schemas, robots, variables, order and scientific settings are compatible."),
            ResearchGlossaryEntry("Scientific contract", "The versioned set of schema, preprocessing, split, model and evaluation rules that gives an artifact its meaning.", "Matching names are insufficient: incompatible contracts must be rejected or quarantined before reuse."),
            ResearchGlossaryEntry("Input feature", "One named input variable supplied to a model in a declared column position.", "Changing its value, unit, normalization, mask or order changes the model input and invalidates an exact replay."),
            ResearchGlossaryEntry("Validation set", "Examples used to tune or stop training while the final test set remains untouched.", "A validation result may guide model choices; a test result must not feed those choices if it is to remain independent.")
        )
}
